import System.Environment (lookupEnv)
import qualified SdkClient as Sdk
import VoxgigStruct (Value (..))
import SdkHelpers (jo)

main :: IO ()
main = do
  mkey <- lookupEnv "{{env}}"
  opts <- jo [("apikey", maybe VNoval VStr mkey)]
  sdk <- Sdk.newSdk opts
  pure ()

